namespace {

struct Stamped {
    Tick tick;
    std::uint64_t tsc;   // read just before push
};

using Queue = RingBuffer<Stamped, SPSC_BUCKETS>;
constexpr std::size_t capacity = SPSC_BUCKETS - 1;

// Static: 3 MB at the default size, too big for the stack.
Queue queue;

// Set by the producer after its last push. Own cache line: the consumer reads it every poll.
alignas(64) std::atomic<bool> done{false};

// No fences: the stamps are only subtracted from each other.
inline std::uint64_t stamp() {
#if defined(__x86_64__)
    return __rdtsc();
#else
    return clock_end();
#endif
}

inline void spin_until(std::uint64_t tsc) {
    while (stamp() < tsc) {}
}

struct Options {
    bool percall = false;
    bool memory = false;
    std::string out;
    std::string variant = "spsc.hpp";
    // udp
    std::string group;                    // empty: unicast
    std::string interface_ip = "127.0.0.1";
    std::uint16_t port = 12345;
    int rcvbuf_bytes = 64 << 20;
    std::size_t record_max = 1 << 21;     // ticks whose timestamps are kept for occupancy
    // memory
    std::string itch_file;
    std::uint64_t from_ns = 34'200ull * 1'000'000'000;   // 09:30:00
    std::uint64_t messages = 20'000'000;
    double speed = 10.0;                  // bursts: times real time, 0 = flat out
    std::size_t depth = 0;                // fixed: ticks kept in the queue
    double period_ns = 0;                 // fixed: one push and one pop every period
    std::uint64_t repeat = 1;             // replays of the window
    // both
    double work_ns = 0;                   // consumer spin after each pop
    std::string perf_ctl;                 // "CTL,ACK": perf control FIFOs
    int producer_core = -1;
    int consumer_core = -1;
};

[[noreturn]] void usage(const char* argv0) {
    std::fprintf(stderr,
                 "usage: %s [--mode e2e|percall] [--out FILE] [--variant NAME]\n"
                 "          [--producer-core N] [--consumer-core N] [--consumer-work-ns N]\n"
                 "          [--perf-ctl CTL_FIFO,ACK_FIFO]\n"
                 "  udp:    [--port N] [--group IP] [--interface IP] [--rcvbuf BYTES] [--record-max N]\n"
                 "  memory: --source memory --itch-file PATH [--from HH:MM:SS] [--messages N]\n"
                 "          [--repeat R] [--speed X] | [--depth D --period-ns T]\n",
                 argv0);
    std::exit(2);
}

std::uint64_t parse_time_of_day(const char* s) {
    unsigned h = 0, m = 0, sec = 0;
    if (std::sscanf(s, "%u:%u:%u", &h, &m, &sec) < 2) {
        std::fprintf(stderr, "bad --from %s, expected HH:MM[:SS]\n", s);
        std::exit(2);
    }
    return ((h * 60ull + m) * 60ull + sec) * 1'000'000'000ull;
}

Options parse_args(int argc, char** argv) {
    Options o;
    for (int i = 1; i < argc; i++) {
        const std::string_view a = argv[i];
        if (i + 1 >= argc) usage(argv[0]);
        const char* v = argv[++i];
        if (a == "--mode") {
            if (std::string_view(v) == "percall") o.percall = true;
            else if (std::string_view(v) != "e2e") usage(argv[0]);
        }
        else if (a == "--source") {
            if (std::string_view(v) == "memory") o.memory = true;
            else if (std::string_view(v) != "udp") usage(argv[0]);
        }
        else if (a == "--out") o.out = v;
        else if (a == "--variant") o.variant = v;
        else if (a == "--group") o.group = v;
        else if (a == "--interface") o.interface_ip = v;
        else if (a == "--port") o.port = static_cast<std::uint16_t>(std::atoi(v));
        else if (a == "--rcvbuf") o.rcvbuf_bytes = std::atoi(v);
        else if (a == "--record-max") o.record_max = std::strtoull(v, nullptr, 10);
        else if (a == "--itch-file") o.itch_file = v;
        else if (a == "--from") o.from_ns = parse_time_of_day(v);
        else if (a == "--messages") o.messages = std::strtoull(v, nullptr, 10);
        else if (a == "--speed") o.speed = std::atof(v);
        else if (a == "--depth") o.depth = std::strtoull(v, nullptr, 10);
        else if (a == "--period-ns") o.period_ns = std::atof(v);
        else if (a == "--consumer-work-ns") o.work_ns = std::atof(v);
        else if (a == "--repeat") o.repeat = std::strtoull(v, nullptr, 10);
        else if (a == "--perf-ctl") o.perf_ctl = v;
        else if (a == "--producer-core") o.producer_core = std::atoi(v);
        else if (a == "--consumer-core") o.consumer_core = std::atoi(v);
        else usage(argv[0]);
    }
    const bool fixed = o.depth > 0 || o.period_ns > 0;
    if (o.memory && o.itch_file.empty()) usage(argv[0]);
    if (o.repeat == 0 || (o.repeat > 1 && !o.memory)) {
        std::fprintf(stderr, "--repeat needs --source memory and a count of at least 1\n");
        std::exit(2);
    }
    if (fixed && (!o.memory || o.depth == 0 || o.period_ns <= 0 || o.depth > capacity || o.work_ns > 0)) {
        std::fprintf(stderr, "fixed occupancy needs --source memory, --depth 1..%zu and --period-ns > 0, "
                             "and no --consumer-work-ns (the period paces the consumer)\n", capacity);
        std::exit(2);
    }
    return o;
}

void pin(int core, const char* who) {
    if (core < 0) return;
    cpu_set_t set;
    CPU_ZERO(&set);
    CPU_SET(core, &set);
    if (const int err = pthread_setaffinity_np(pthread_self(), sizeof set, &set); err != 0) {
        std::fprintf(stderr, "%s: cannot pin to core %d: %s\n", who, core, std::strerror(err));
        std::exit(2);
    }
}

void name_thread(const char* name) {
    pthread_setname_np(pthread_self(), name);
}

// perf's --control fifo:CTL,ACK protocol: write a command to CTL, perf answers "ack\n" on ACK.
class PerfControl {
public:
    explicit PerfControl(const std::string& spec) {
        if (spec.empty()) return;
        const std::size_t comma = spec.find(',');
        if (comma == std::string::npos) {
            std::fprintf(stderr, "--perf-ctl expects CTL_FIFO,ACK_FIFO\n");
            std::exit(2);
        }
        // Non-blocking opens, so a run without perf fails here instead of hanging:
        // opening CTL for writing fails with ENXIO when nobody has it open for reading.
        ctl_ = ::open(spec.substr(0, comma).c_str(), O_WRONLY | O_NONBLOCK | O_CLOEXEC);
        ack_ = ::open(spec.substr(comma + 1).c_str(), O_RDONLY | O_NONBLOCK | O_CLOEXEC);
        if (ctl_ < 0 || ack_ < 0) {
            std::perror("--perf-ctl (is perf running with --control fifo:CTL,ACK?)");
            std::exit(2);
        }
        ::fcntl(ack_, F_SETFL, ::fcntl(ack_, F_GETFL) & ~O_NONBLOCK);   // wait for each ack
    }
    ~PerfControl() {
        if (ctl_ >= 0) ::close(ctl_);
        if (ack_ >= 0) ::close(ack_);
    }
    PerfControl(const PerfControl&) = delete;
    PerfControl& operator=(const PerfControl&) = delete;

    void enable() { send("enable\n"); }
    void disable() { send("disable\n"); }

private:
    void send(std::string_view cmd) {
        if (ctl_ < 0) return;
        if (::write(ctl_, cmd.data(), cmd.size()) != static_cast<ssize_t>(cmd.size())) {
            std::perror("--perf-ctl write");
            return;
        }
        char c = 0;
        while (c != '\n') {
            if (::read(ack_, &c, 1) != 1) {
                std::perror("--perf-ctl ack");
                return;
            }
        }
    }

    int ctl_ = -1;
    int ack_ = -1;
};

// Minor page faults taken by the calling thread so far.
long minor_faults() {
    rusage r{};
    getrusage(RUSAGE_THREAD, &r);
    return r.ru_minflt;
}

// Maps every page of the queue. Results are not checked: a queue that misbehaves here
// is caught by the validity check at the end of the run.
void pretouch_queue() {
    for (std::size_t i = 0; i < SPSC_BUCKETS; i++) {
        queue.push(Stamped{});
        queue.pop();
    }
}

// The --from/--messages window of an ITCH file, decoded into ticks.
struct Window {
    std::vector<Tick> ticks;
    std::uint64_t messages = 0;
    std::uint64_t malformed = 0;
    std::uint64_t qty = 0;
};

Window load_window(const Options& o) {
    const int fd = ::open(o.itch_file.c_str(), O_RDONLY);
    if (fd < 0) {
        std::perror(o.itch_file.c_str());
        std::exit(2);
    }
    struct stat st{};
    ::fstat(fd, &st);
    const std::size_t size = static_cast<std::size_t>(st.st_size);
    void* map = ::mmap(nullptr, size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (map == MAP_FAILED) {
        std::perror("mmap");
        std::exit(2);
    }
    ::madvise(map, size, MADV_SEQUENTIAL);
    const auto* data = static_cast<const std::uint8_t*>(map);

    Window w;
    std::size_t off = 0;
    // Skip to --from, as itch-replay does
    while (off + 2 <= size) {
        const std::size_t len = itch::load_be<2>(data + off);
        if (off + 2 + len > size) break;
        if (len >= itch::header_size && itch::load_be<6>(data + off + 2 + 5) >= o.from_ns) break;
        off += 2 + len;
    }
    while (w.messages < o.messages && off + 2 <= size) {
        const std::size_t len = itch::load_be<2>(data + off);
        if (off + 2 + len > size) break;   // truncated last message
        ++w.messages;
        Tick t;
        switch (itch::decode_tick(data + off + 2, len, 0, t)) {
            case itch::Decoded::tick:
                w.ticks.push_back(t);
                w.qty += static_cast<std::uint64_t>(t.qty);
                break;
            case itch::Decoded::malformed: ++w.malformed; break;
            case itch::Decoded::skipped: break;
        }
        off += 2 + len;
    }
    ::munmap(map, size);
    ::close(fd);
    return w;
}

// Enough for the per-call rows in every run so far; going over it means a reallocation on
// the hot path. The e2e row gets one slot per recorded tick, since queueing can make every
// e2e sample long.
constexpr std::size_t long_samples = 1 << 16;

// Allocates and maps n entries up front, so recording never faults or allocates.
std::vector<std::uint64_t> prefaulted(std::size_t n) {
    std::vector<std::uint64_t> v(n, 0);
    return v;
}

template <bool PerCall>
struct Producer {
    explicit Producer(std::size_t record) : push_tsc(prefaulted(record)) { push.prefault_long(long_samples); }

    Histogram push;
    std::vector<std::uint64_t> push_tsc;   // stamp of each push, for occupancy
    std::uint64_t pushed = 0;
    std::uint64_t full = 0;
    std::uint64_t qty = 0;
    std::uint64_t first_tsc = 0;
    std::uint64_t measure_from = 0;        // pushes before this one are not in the push row

    void on_tick(const Tick& t) {
        const Stamped s{t, stamp()};
        bool ok;
        if constexpr (PerCall) {
            const std::uint64_t t0 = clock_begin();
            ok = queue.push(s);
            const std::uint64_t t1 = clock_end();
            if (pushed >= measure_from) push.add(t1 - t0);
        } else {
            ok = queue.push(s);
        }
        if (!ok) [[unlikely]] {
            ++full;
            while (!queue.push(s)) {}
        }
        if (pushed == 0) first_tsc = s.tsc;
        if (pushed < push_tsc.size()) push_tsc[pushed] = s.tsc;
        ++pushed;
        qty += static_cast<std::uint64_t>(t.qty);
    }
};

struct Consumer {
    // record: ticks whose pop stamp is kept. e2e_long: room for long e2e samples, which at
    // high occupancy is every tick.
    Consumer(std::size_t record, std::size_t e2e_long) : pop_tsc(prefaulted(record)) {
        pop.prefault_long(long_samples);
        pop_empty.prefault_long(long_samples);
        e2e.prefault_long(std::max(e2e_long, long_samples));
    }

    Histogram pop;
    Histogram pop_empty;
    Histogram e2e;
    std::vector<std::uint64_t> pop_tsc;    // stamp after each pop, for occupancy
    std::uint64_t popped = 0;
    std::uint64_t measured = 0;   // pops in the e2e and pop rows
    std::uint64_t empty = 0;   // polls that found nothing, counted from the first tick on
    std::uint64_t qty = 0;
    std::uint64_t last_tsc = 0;
    long page_faults = 0;
};

// How the consumer is slowed down or paced. All times in TSC counts.
struct ConsumerPlan {
    std::uint64_t work = 0;          // spin after each pop
    std::uint64_t t0 = 0;            // fixed: pop j is due at t0 + j * period
    std::uint64_t period = 0;
    std::uint64_t measure_from = 0;  // pops outside [from, to) are not in the rows
    std::uint64_t measure_to = ~0ull;
};

template <bool PerCall>
void consume(Consumer& c, const ConsumerPlan& p) {
    name_thread("spsc-consumer");
    for (;;) {
        if (p.period) spin_until(p.t0 + c.popped * p.period);
        // Read before the pop: if the producer had finished, an empty pop means drained.
        const bool was_done = done.load(std::memory_order_acquire);
        std::uint64_t t0 = 0, t1 = 0;
        if constexpr (PerCall) t0 = clock_begin();
        const auto v = queue.pop();
        if constexpr (PerCall) t1 = clock_end();
        const bool measured = c.popped >= p.measure_from && c.popped < p.measure_to;

        if (v) {
            const std::uint64_t now = stamp();
            if (measured) {
                ++c.measured;
                c.e2e.add(now - v->tsc);
                if constexpr (PerCall) c.pop.add(t1 - t0);
            }
            if (c.popped < c.pop_tsc.size()) c.pop_tsc[c.popped] = now;
            ++c.popped;
            c.qty += static_cast<std::uint64_t>(v->tick.qty);
            c.last_tsc = now;
            if (p.work) spin_until(now + p.work);
        } else {
            if (was_done) return;
            if (c.popped != 0 && measured) {
                ++c.empty;
                if constexpr (PerCall) c.pop_empty.add(t1 - t0);
            }
        }
    }
}

// Ticks in the queue when each push happened: pushes before it minus pops before it.
struct Occupancy {
    std::uint64_t samples = 0;
    std::uint64_t p50 = 0, p90 = 0, p99 = 0, max = 0;
    double mean = 0;
    double above_half = 0;       // fraction of pushes that found the queue at least half full
    double above_90 = 0;         // ... at least 90% full
};

Occupancy occupancy(const std::vector<std::uint64_t>& push_tsc, std::uint64_t pushed,
                    const std::vector<std::uint64_t>& pop_tsc, std::uint64_t popped, std::uint64_t from) {
    const std::uint64_t npush = std::min<std::uint64_t>(pushed, push_tsc.size());
    const std::uint64_t npop = std::min<std::uint64_t>(popped, pop_tsc.size());
    std::vector<std::uint32_t> occ;
    occ.reserve(npush > from ? npush - from : 0);
    std::uint64_t j = 0;
    for (std::uint64_t i = 0; i < npush; i++) {
        while (j < npop && j < i && pop_tsc[j] < push_tsc[i]) ++j;
        if (i >= from) occ.push_back(static_cast<std::uint32_t>(i - j));
    }
    Occupancy r;
    if (occ.empty()) return r;
    r.samples = occ.size();
    double sum = 0;
    std::uint64_t half = 0, ninety = 0;
    for (std::uint32_t x : occ) {
        sum += x;
        half += x * 2 >= capacity;
        ninety += x * 10 >= capacity * 9;
    }
    r.mean = sum / static_cast<double>(occ.size());
    r.above_half = static_cast<double>(half) / static_cast<double>(occ.size());
    r.above_90 = static_cast<double>(ninety) / static_cast<double>(occ.size());
    std::sort(occ.begin(), occ.end());
    const auto q = [&](double f) { return occ[std::min(occ.size() - 1, static_cast<std::size_t>(f * static_cast<double>(occ.size())))]; };
    r.p50 = q(0.50);
    r.p90 = q(0.90);
    r.p99 = q(0.99);
    r.max = occ.back();
    return r;
}

struct Row {
    const char* name;
    double p50, p99, p999, p9999, max;
    std::uint64_t samples;
};

// net: subtract the timer overhead (per-call rows). e2e rows are two plain TSC reads.
Row row(const char* name, Histogram& h, const ClockInfo& ck, std::uint64_t samples, bool net) {
    const auto ns = [&](std::uint64_t counts) {
        if (net) counts = counts > ck.overhead ? counts - ck.overhead : 0;
        return static_cast<double>(counts) * ck.ns_per_count;
    };
    return {name, ns(h.quantile(0.50)), ns(h.quantile(0.99)), ns(h.quantile(0.999)),
            ns(h.quantile(0.9999)), ns(h.max()), samples};
}

// What the traffic source reports, the same for both sources.
struct SourceInfo {
    std::uint64_t messages = 0;
    std::uint64_t ticks = 0;
    std::uint64_t lost = 0;
    std::uint64_t malformed = 0;
    std::uint64_t packets = 0;
    bool complete = true;     // udp: end of session seen
};

void write_json(const Options& o, const ClockInfo& ck, const Row* rows, std::size_t nrows, const SourceInfo& s,
                std::uint64_t full, std::uint64_t empty, double mticks_per_s, const Occupancy& occ) {
    std::FILE* f = std::fopen(o.out.c_str(), "w");
    if (!f) {
        std::perror(o.out.c_str());
        std::exit(2);
    }
    std::fprintf(f,
                 "{\n  \"context\": {\"variant\": \"%s\", \"mode\": \"%s\", \"buckets\": %d,\n"
                 "    \"source\": \"%s\", \"speed\": %.3f, \"depth\": %zu, \"period_ns\": %.1f, \"work_ns\": %.1f, \"repeat\": %llu,\n"
                 "    \"clock_step_ns\": %.3f, \"timer_overhead_ns\": %.3f, \"messages\": %llu, \"ticks\": %llu,\n"
                 "    \"lost_messages\": %llu, \"full\": %llu, \"empty_polls\": %llu, \"mticks_per_s\": %.3f,\n"
                 "    \"occupancy_p50\": %llu, \"occupancy_p90\": %llu, \"occupancy_p99\": %llu, "
                 "\"occupancy_max\": %llu, \"occupancy_mean\": %.1f,\n"
                 "    \"occupancy_above_half\": %.4f, \"occupancy_above_90pct\": %.4f},\n"
                 "  \"benchmarks\": [\n",
                 o.variant.c_str(), o.percall ? "percall" : "e2e", SPSC_BUCKETS, o.memory ? "memory" : "udp",
                 o.speed, o.depth, o.period_ns, o.work_ns, static_cast<unsigned long long>(o.repeat), ck.step_ns,
                 static_cast<double>(ck.overhead) * ck.ns_per_count, static_cast<unsigned long long>(s.messages),
                 static_cast<unsigned long long>(s.ticks), static_cast<unsigned long long>(s.lost),
                 static_cast<unsigned long long>(full), static_cast<unsigned long long>(empty), mticks_per_s,
                 static_cast<unsigned long long>(occ.p50), static_cast<unsigned long long>(occ.p90),
                 static_cast<unsigned long long>(occ.p99), static_cast<unsigned long long>(occ.max), occ.mean,
                 occ.above_half, occ.above_90);
    for (std::size_t i = 0; i < nrows; i++) {
        const Row& r = rows[i];
        std::fprintf(f,
                     "    {\"name\": \"%s\", \"run_name\": \"%s\", \"run_type\": \"iteration\", "
                     "\"iterations\": %llu, \"time_unit\": \"ns\", \"p50\": %.2f, \"p99\": %.2f, "
                     "\"p99.9\": %.2f, \"p99.99\": %.2f, \"max\": %.2f}%s\n",
                     r.name, r.name, static_cast<unsigned long long>(r.samples), r.p50, r.p99, r.p999, r.p9999,
                     r.max, i + 1 < nrows ? "," : "");
    }
    std::fprintf(f, "  ]\n}\n");
    std::fclose(f);
}

template <bool PerCall>
int report(const Options& o, const ClockInfo& ck, Producer<PerCall>& producer, Consumer& consumer,
           const SourceInfo& s, long producer_faults, std::uint64_t push_from) {
    const double seconds = consumer.popped ? static_cast<double>(consumer.last_tsc - producer.first_tsc)
                                                 * ck.ns_per_count / 1e9
                                           : 0.0;
    const double mticks = seconds > 0 ? static_cast<double>(consumer.popped) / seconds / 1e6 : 0.0;
    const Occupancy occ = occupancy(producer.push_tsc, producer.pushed, consumer.pop_tsc, consumer.popped, push_from);

    Row rows[4];
    std::size_t nrows = 0;
    if constexpr (PerCall) {
        rows[nrows++] = row("spsc/percall/push", producer.push, ck, producer.pushed - push_from, true);
        rows[nrows++] = row("spsc/percall/pop", consumer.pop, ck, consumer.measured, true);
        rows[nrows++] = row("spsc/percall/pop_empty", consumer.pop_empty, ck, consumer.empty, true);
        rows[nrows++] = row("spsc/percall/e2e", consumer.e2e, ck, consumer.measured, false);
    } else {
        rows[nrows++] = row("spsc/e2e/e2e", consumer.e2e, ck, consumer.measured, false);
    }

    std::printf("variant %s, %s, RingBuffer<%zu-byte payload, %d>\n", o.variant.c_str(),
                PerCall ? "percall" : "e2e", sizeof(Stamped), SPSC_BUCKETS);
    if (o.memory) {
        if (o.depth) std::printf("source memory, fixed occupancy: depth %zu, period %.1f ns\n", o.depth, o.period_ns);
        else std::printf("source memory, bursts: speed %g, consumer work %.1f ns\n", o.speed, o.work_ns);
    } else if (o.work_ns > 0) {
        std::printf("source udp, consumer work %.1f ns\n", o.work_ns);
    }
    std::printf("clock step %.2f ns, timer overhead %.2f ns%s\n", ck.step_ns,
                static_cast<double>(ck.overhead) * ck.ns_per_count,
                ck.step_ns > 5.0 ? "  (step too coarse: percentiles NOT meaningful here)" : "");
    std::printf("%-24s %10s %9s %9s %9s %9s %10s\n", "ns", "samples", "p50", "p99", "p99.9", "p99.99", "max");
    for (std::size_t i = 0; i < nrows; i++)
        std::printf("%-24s %10llu %9.1f %9.1f %9.1f %9.1f %10.1f\n", rows[i].name,
                    static_cast<unsigned long long>(rows[i].samples), rows[i].p50, rows[i].p99, rows[i].p999,
                    rows[i].p9999, rows[i].max);
    std::printf("occupancy at push (of %zu): p50 %llu, p90 %llu, p99 %llu, max %llu, mean %.0f; "
                "%.1f%% of pushes at least half full, %.1f%% at least 90%% full (%llu pushes)\n",
                capacity, static_cast<unsigned long long>(occ.p50), static_cast<unsigned long long>(occ.p90),
                static_cast<unsigned long long>(occ.p99), static_cast<unsigned long long>(occ.max), occ.mean,
                100 * occ.above_half, 100 * occ.above_90, static_cast<unsigned long long>(occ.samples));
    if (producer.pushed > producer.push_tsc.size())
        std::printf("note: occupancy covers the first %zu of %llu pushes (--record-max)\n", producer.push_tsc.size(),
                    static_cast<unsigned long long>(producer.pushed));
    std::printf("packets %llu, messages %llu, ticks %llu, lost %llu, malformed %llu; "
                "full %llu, empty polls %llu; %.2f M ticks/s first push to last pop\n",
                static_cast<unsigned long long>(s.packets), static_cast<unsigned long long>(s.messages),
                static_cast<unsigned long long>(s.ticks), static_cast<unsigned long long>(s.lost),
                static_cast<unsigned long long>(s.malformed), static_cast<unsigned long long>(producer.full),
                static_cast<unsigned long long>(consumer.empty), mticks);
    std::printf("minor page faults during the run: producer %ld, consumer %ld\n", producer_faults,
                consumer.page_faults);
    std::printf("summary: messages=%llu ticks=%llu qty=%llu\n", static_cast<unsigned long long>(s.messages),
                static_cast<unsigned long long>(consumer.popped), static_cast<unsigned long long>(consumer.qty));

    if (!o.out.empty()) write_json(o, ck, rows, nrows, s, producer.full, consumer.empty, mticks, occ);

    const bool valid = s.complete && s.lost == 0 && s.malformed == 0 && consumer.popped == s.ticks &&
                       producer.pushed == s.ticks && consumer.qty == producer.qty;
    if (!valid) {
        std::printf("INVALID RUN: %s\n", s.lost || s.malformed ? "packets lost or malformed"
                                                               : "consumer and producer disagree");
        return 3;
    }
    return 0;
}

template <bool PerCall>
int run_udp(const Options& o, const ClockInfo& ck) {
    Producer<PerCall> producer(o.record_max);
    Consumer consumer(o.record_max, o.record_max);
    const ConsumerPlan plan{.work = static_cast<std::uint64_t>(o.work_ns / ck.ns_per_count)};
    PerfControl perf(o.perf_ctl);

    // Bound in the constructor; "ready" tells spsc-bench.sh it can start the sender.
    ItchParser<Producer<PerCall>&> parser(producer, {.group = o.group,
                                                     .interface_ip = o.interface_ip,
                                                     .port = o.port,
                                                     .rcvbuf_bytes = o.rcvbuf_bytes});
    pin(o.producer_core, "producer");
    name_thread("spsc-producer");
    pretouch_queue();

    std::printf("ready\n");
    std::fflush(stdout);

    std::thread consumer_thread([&] {
        pin(o.consumer_core, "consumer");
        const long faults_before = minor_faults();
        consume<PerCall>(consumer, plan);
        consumer.page_faults = minor_faults() - faults_before;
    });

    // Includes the wait for the sender's first packet
    perf.enable();
    const long faults_before = minor_faults();
    parser.start();
    const long producer_faults = minor_faults() - faults_before;
    done.store(true, std::memory_order_release);
    consumer_thread.join();
    perf.disable();

    const auto& st = parser.stats();
    const SourceInfo s{.messages = st.messages, .ticks = st.ticks, .lost = st.lost_messages,
                       .malformed = st.malformed, .packets = st.packets, .complete = st.end_of_session};
    return report<PerCall>(o, ck, producer, consumer, s, producer_faults, 0);
}

template <bool PerCall>
int run_memory(const Options& o, const ClockInfo& ck) {
    PerfControl perf(o.perf_ctl);   // before decoding, so a wrong --perf-ctl fails at once
    const Window w = load_window(o);
    const std::vector<Tick>& ticks = w.ticks;
    const std::uint64_t n = ticks.size();
    const std::uint64_t total = n * o.repeat;   // ticks pushed: the window, o.repeat times
    if (n == 0 || (o.depth && o.depth * 2 >= total)) {
        std::fprintf(stderr, "window has %llu ticks: too few%s\n", static_cast<unsigned long long>(n),
                     o.depth ? " for this --depth (need more than 2 x depth in total)" : "");
        return 2;
    }
    std::printf("loaded %llu ticks from %llu messages, replayed %llu time(s)\n", static_cast<unsigned long long>(n),
                static_cast<unsigned long long>(w.messages), static_cast<unsigned long long>(o.repeat));

    // Stamps for occupancy are kept for the first record_cap ticks (8 bytes each per thread)
    constexpr std::uint64_t record_cap = 4'000'000;
    const std::size_t record = std::min(total, record_cap);
    Producer<PerCall> producer(record);
    Consumer consumer(record, total);
    const auto counts = [&](double ns) { return static_cast<std::uint64_t>(ns / ck.ns_per_count); };
    const std::uint64_t ms = counts(1e6);
    ConsumerPlan plan{.work = counts(o.work_ns)};

    pin(o.producer_core, "producer");
    name_thread("spsc-producer");
    pretouch_queue();
    std::printf("ready\n");
    std::fflush(stdout);

    std::thread consumer_thread;
    const auto start_consumer = [&] {
        consumer_thread = std::thread([&] {
            pin(o.consumer_core, "consumer");
            const long faults_before = minor_faults();
            consume<PerCall>(consumer, plan);
            consumer.page_faults = minor_faults() - faults_before;
        });
    };

    // Counted from after the consumer thread is created, which faults on its own.
    long faults_before = 0;
    std::uint64_t push_from = 0;
    if (o.depth) {
        // Pre-fill, then push tick k at t0 + (k - depth) * period while the consumer pops
        // tick j at t0 + j * period: depth ticks stay in the queue.
        for (std::uint64_t k = 0; k < o.depth; k++) producer.on_tick(ticks[k % n]);
        push_from = o.depth;
        producer.measure_from = o.depth;
        const std::uint64_t period = counts(o.period_ns);
        plan.period = period;
        plan.t0 = stamp() + ms;
        plan.measure_from = o.depth;
        plan.measure_to = total - o.depth;
        start_consumer();
        perf.enable();
        faults_before = minor_faults();
        for (std::uint64_t k = o.depth; k < total; k++) {
            spin_until(plan.t0 + (k - o.depth) * period);
            producer.on_tick(ticks[k % n]);
        }
    } else {
        start_consumer();
        perf.enable();
        faults_before = minor_faults();
        const std::uint64_t t0 = stamp() + ms;
        const std::int64_t ts0 = ticks.front().ts_ns;
        // Each replay starts 1 ms of market time after the previous one ends
        const std::int64_t span = ticks.back().ts_ns - ts0 + 1'000'000;
        for (std::uint64_t k = 0; k < total; k++) {
            const Tick& t = ticks[k % n];
            const std::int64_t market = t.ts_ns - ts0 + static_cast<std::int64_t>(k / n) * span;
            if (o.speed > 0) spin_until(t0 + counts(static_cast<double>(market) / o.speed));
            producer.on_tick(t);
        }
    }
    const long producer_faults = minor_faults() - faults_before;
    done.store(true, std::memory_order_release);
    consumer_thread.join();
    perf.disable();

    const SourceInfo s{.messages = w.messages * o.repeat, .ticks = total, .malformed = w.malformed * o.repeat};
    return report<PerCall>(o, ck, producer, consumer, s, producer_faults, push_from);
}

}  // namespace

int main(int argc, char** argv) {
    const Options o = parse_args(argc, argv);
    const ClockInfo& ck = clock_info();   // 50 ms calibration, before any traffic
    if (o.memory) return o.percall ? run_memory<true>(o, ck) : run_memory<false>(o, ck);
    return o.percall ? run_udp<true>(o, ck) : run_udp<false>(o, ck);
}
